function paragraph(text,style='Normal'){return `<w:p><w:pPr><w:pStyle w:val="${style}"/></w:pPr><w:r><w:t xml:space="preserve">${esc(text)}</w:t></w:r></w:p>`}
function tableXml(rows){return `<w:tbl><w:tblPr><w:tblBorders><w:top w:val="single" w:sz="4" w:color="C9D4D0"/><w:left w:val="single" w:sz="4" w:color="C9D4D0"/><w:bottom w:val="single" w:sz="4" w:color="C9D4D0"/><w:right w:val="single" w:sz="4" w:color="C9D4D0"/><w:insideH w:val="single" w:sz="4" w:color="DCE3E0"/><w:insideV w:val="single" w:sz="4" w:color="DCE3E0"/></w:tblBorders></w:tblPr>${rows.map((row,ri)=>`<w:tr>${row.map(cell=>`<w:tc><w:tcPr><w:tcW w:w="2200" w:type="dxa"/>${ri===0?'<w:shd w:fill="E9F2EE"/>':''}</w:tcPr><w:p><w:r>${ri===0?'<w:rPr><w:b/></w:rPr>':''}<w:t xml:space="preserve">${esc(cell)}</w:t></w:r></w:p></w:tc>`).join('')}</w:tr>`).join('')}</w:tbl>`}
function reportXml(s){const snap=s.snapshot,v=snap.venture,c=snap.calc,e=snap.evaluation,products=snap.products,active=snap.expenses.filter(x=>x.enabled),ops=active.filter(x=>x.kind!=='startup'),starts=active.filter(x=>x.kind==='startup'),competitors=snap.competitors.competitors;let body=paragraph('Pricing Decision Report','Title')+paragraph(`Confirmed ${new Date(s.confirmedAt).toLocaleString()} · Currency USD · Monthly operating view`,'Subtitle')+paragraph('1. Venture Overview','Heading1')+paragraph(`Venture: ${v.name}`)+paragraph(`Concept: ${v.concept}`)+paragraph(`Target customers: ${v.target_customers}`)+paragraph(`Value proposition: ${v.value_proposition}`)+paragraph(`Distribution and geography: ${v.distribution}; ${v.geography}`)+paragraph('2. Website Information','Heading1')+paragraph(`Original venture website repository: ${v.original_repository}`)+paragraph(`Original live venture website URL: ${v.original_live_website}`)+paragraph('The repository is the Mission 2 competitive research dashboard; no separate commercial venture website URL was supplied in Mission 3 setup.')+paragraph('3. Final Pricing Decision','Heading1')+tableXml([['Product / plan','Price','Billing','Features / add-ons'],...products.map(p=>[p.name,`${fmt(p.price)} ${p.currency||'USD'}`,p.model,p.features+' | Add-ons: '+p.addons])])+paragraph(`Student justification: ${s.justification}`)+paragraph('4. Cost Assumptions','Heading1')+paragraph('Operating costs (monthly and variable; only enabled lines shown)','Heading2')+tableXml([['Expense','Amount / basis','Treatment','Evidence / assumption','Source'],...ops.map(x=>[x.name,x.kind==='percent'?`${x.amount}% of price`:x.kind==='payment'?`${x.amount}% + ${fmt(x.flatFee)}/transaction`:x.kind==='perunit'?`${fmt(x.amount)}/pass`:`${fmt(x.amount)} / ${x.frequency}`,x.classification+' · '+x.frequency,x.evidence+' · '+x.assumptions,x.source_url||'No source; estimate/illustrative'])])+paragraph('Startup cash and capitalized setup (not recurring annual expenses)','Heading2')+tableXml([['Startup item','Cash amount','Monthly treatment','Useful life / evidence'],...starts.map(x=>[x.name,fmt(x.amount),x.breakEven&&x.amortizationMonths?`${fmt(x.amount/x.amortizationMonths)}/mo amortization`:'Excluded from break-even',`${x.amortizationMonths||'—'} months · ${x.evidence} · ${x.assumptions}`])])+paragraph(`Total modeled startup cash requirement: ${fmt(c.startup)}. Total monthly accounting-style fixed costs, including amortization/depreciation: ${fmt(c.fixed)}.`)+paragraph('5. Financial Results','Heading1')+tableXml([['Metric','Monthly result / assumption'],['Fixed operating costs incl. monthly amortization',fmt(c.fixed)],['Variable costs at entered volumes',fmt(c.variable)],['Revenue at entered volumes',fmt(c.revenue)],['Operating result',fmt(c.profit)],['Contribution per weighted sale',c.weightedContribution==null?'—':fmt(c.weightedContribution)],['Break-even sales/month',c.breakEven==null?'Not attainable at current contribution':String(Math.ceil(c.breakEven))],['Margin of safety',c.marginOfSafety==null?'Not available':`${(c.marginOfSafety*100).toFixed(1)}%`],['Expected sales',`${nfmt(c.units)} sales/month · student assumption, not forecast`]])+paragraph(`Pricing model horizon: monthly normalized. Annual subscriptions are divided by 12; transaction-based variable fees are also spread across 12 months. Sales mix is the entered monthly quantity mix. Startup cash is separately reported; capitalized startup items are amortized over the student's stated useful life.`)+paragraph('6. Competitive Positioning','Heading1')+paragraph('Mission 1 research checked October 27, 2026. Prices are research snapshots, not live quotes.')+tableXml([['Competitor','Classification','Relevant observed price','Verification / limitation'],...competitors.map(k=>{let os=snap.competitors.pricing_offers.filter(o=>o.competitor_id===k.competitor_id&&o.representative);let txt=os.map(o=>o.current_price==null?'Price unavailable':`${fmt(o.current_price)}/${o.pricing_unit}${o.promotional_price?' (promotional)':''}`).join('; ');return[k.name,k.classification,txt||'No representative price',os.map(o=>o.verification_status).join(', ')]})])+paragraph(`Preliminary Mission 1 recommendation: ${snap.competitors.preliminary_recommendation.low}–${snap.competitors.preliminary_recommendation.high} USD per event. Confirmed price(s): ${products.map(p=>`${p.name} ${fmt(p.price)}/${p.model==='year'?'year':p.model==='month'?'month':'event'}`).join('; ')}`)+paragraph('7. Pricing Decision Review','Heading1')+paragraph(`Overall classification: ${e.risk}. This is a transparent rule-based classification of the entered model, not a probability of business failure.`)+paragraph('Financial findings','Heading2')+e.financial.map(x=>paragraph('• '+x)).join('')+paragraph('Competitive findings','Heading2')+e.competitive.map(x=>paragraph('• '+x)).join('')+paragraph('Evidence limitations','Heading2')+e.evidence.map(x=>paragraph('• '+x)).join('')+paragraph('Recommendations','Heading2')+e.recommendations.map(x=>paragraph('• '+x)).join('')+paragraph(`Warnings acknowledged by student: ${s.warningsAcknowledged?'Yes — student checked the warning acknowledgement.':'No material warning acknowledgement recorded.'}`)+paragraph('8. Student Decision Statement','Heading1')+paragraph(s.justification)+paragraph('9. Sources and Limitations','Heading1')+snap.sources.map(x=>paragraph(`${x.name} — ${x.url} (checked ${x.checked}). ${x.note}`)).join('')+data.limitations.map(x=>paragraph('• '+x)).join('')+paragraph('10. Confirmation Record','Heading1')+tableXml([['Record','Value'],['Confirmation date',new Date(s.confirmedAt).toLocaleString()],['Final selected prices',products.map(p=>`${p.name}: ${fmt(p.price)} ${p.currency||'USD'} / ${p.model}`).join('; ')],['Evaluation status','Current at confirmation'],['Confirmation status','Student-confirmed snapshot'],['Warnings acknowledged',s.warningsAcknowledged?'Yes':'No']])+`<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1000" w:right="1000" w:bottom="1000" w:left="1000"/></w:sectPr>`;return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}</w:body></w:document>`}
function crc32(bytes){let crc=-1;for(const b of bytes){crc^=b;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return(crc^-1)>>>0}
function zipStore(files){const enc=new TextEncoder(),locals=[],centrals=[];let offset=0;for(const [name,content] of Object.entries(files)){const nb=enc.encode(name),db=enc.encode(content),crc=crc32(db),lh=new Uint8Array(30+nb.length),lv=new DataView(lh.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x0800,true);lv.setUint16(8,0,true);lv.setUint32(14,crc,true);lv.setUint32(18,db.length,true);lv.setUint32(22,db.length,true);lv.setUint16(26,nb.length,true);lh.set(nb,30);locals.push(lh,db);const ch=new Uint8Array(46+nb.length),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x0800,true);cv.setUint16(10,0,true);cv.setUint32(16,crc,true);cv.setUint32(20,db.length,true);cv.setUint32(24,db.length,true);cv.setUint16(28,nb.length,true);cv.setUint32(42,offset,true);ch.set(nb,46);centrals.push(ch);offset+=lh.length+db.length}const cd=centrals.reduce((s,x)=>s+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,centrals.length,true);ev.setUint16(10,centrals.length,true);ev.setUint32(12,cd,true);ev.setUint32(16,offset,true);return new Blob([...locals,...centrals,end],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})}
function makeDocx(s){const styles=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:rPr><w:rFonts w:ascii="Aptos" w:hAnsi="Aptos"/><w:sz w:val="20"/><w:color w:val="243239"/></w:rPr><w:pPr><w:spacing w:after="100"/></w:pPr></w:style><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:rPr><w:rFonts w:ascii="Aptos Display" w:hAnsi="Aptos Display"/><w:b/><w:sz w:val="36"/><w:color w:val="14705A"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/><w:rPr><w:sz w:val="18"/><w:color w:val="64736F"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:spacing w:before="260" w:after="120"/><w:keepNext/></w:pPr><w:rPr><w:b/><w:sz w:val="26"/><w:color w:val="14705A"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:basedOn w:val="Normal"/><w:pPr><w:spacing w:before="180" w:after="80"/><w:keepNext/></w:pPr><w:rPr><w:b/><w:sz w:val="22"/><w:color w:val="324C45"/></w:rPr></w:style></w:styles>`;const rel=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`;const types=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>`;const docrels=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`;return zipStore({'[Content_Types].xml':types,'_rels/.rels':rel,'word/document.xml':reportXml(s),'word/styles.xml':styles,'word/_rels/document.xml.rels':docrels})}
function confirmedSnapshot(){if(!state.confirmed||state.confirmed.version!==state.version||!state.evaluation||state.evaluation.version!==state.version)return null;return{...clone(state.confirmed),snapshot:clone(state.confirmed.snapshot)}}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function snapshotScenario(){return{expenses:clone(state.expenses),products:clone(state.products)}}
function applyScenario(name){if(name===state.scenario)return;state.scenarioStates[state.scenario]=snapshotScenario();const existing=state.scenarioStates[name];if(existing){state.expenses=clone(existing.expenses);state.products=clone(existing.products)}else{const preset=data.scenarios.find(x=>x.name===name);if(preset){state.expenses=data.expenses.map(e=>{const x=clone(e);if(x.kind==='fixed'&&x.frequency==='month')x.amount=Number(x.amount)*preset.factor;return x});state.products=clone(data.products).map(p=>({...p,quantity:preset.quantity}))}else{toast('Scenario not found.');return}}state.scenario=name;state.evaluation=null;state.confirmed=null;state.version++;save();render();toast(`${name} assumptions loaded.`)}
function addExpense(){const name=prompt('Name this expense');if(!name?.trim())return;state.expenses.push({id:uid(),name:name.trim(),category:'Student added',description:'Student-defined venture expense.',kind:'fixed',classification:'Fixed',frequency:'month',amount:0,unit:'USD/month',range:{min:0,max:5000,step:10},benchmark:null,evidence:'Student-Entered',source_url:'',allocation:'Shared business overhead',assumptions:'Enter the source or explain the assumption.',enabled:true,breakEven:true,custom:true});changed();render();toast('Expense added.')}
function addProduct(){const p={id:uid(),name:'New student scenario',description:'Hypothetical offer for exploration. Not documented as an existing product.',model:'event',price:9.99,quantity:0,unitCost:0,currency:'USD',features:'Describe customer-facing features',addons:'None specified',assumptions:'Student-created scenario; validate offer and rights.',isScenario:true,enabled:true};state.products.push(p);selectedProductId=p.id;changed();render();$('#products').scrollIntoView({behavior:'smooth'});toast('Student scenario added.')}
function handleExpense(el){const e=state.expenses.find(x=>x.id===el.dataset.exp);if(!e)return;const f=el.dataset.field;if(f==='enabled'||f==='breakEven')e[f]=el.checked;else if(f==='allocation'){e.allocation=el.value;if(el.value==='Product-specific'&&!(e.productIds||[]).length)e.productIds=activeProducts().slice(0,1).map(p=>p.id)}else if(f==='productIds')e.productIds=[...el.selectedOptions].map(o=>o.value);else if(f==='amount'||f==='flatFee'||f==='amortizationMonths')e[f]=Number(el.value)||0;else if(f==='kind'){e.kind=el.value;e.classification=el.value==='fixed'?'Fixed':el.value==='startup'?'Capitalized startup':'Variable';e.frequency=el.value==='fixed'?'month':el.value==='startup'?'one-time':'per sale';e.unit=el.value==='percent'?'% of gross ticket revenue':el.value==='payment'?'% + fixed fee / sale':el.value==='startup'?'USD one-time':'USD / pass'}else if(f==='frequency')e.frequency=el.value;else e[f]=el.value;changed();render();}
function handleProduct(el){const p=state.products.find(x=>x.id===el.dataset.product);if(!p)return;const f=el.dataset.field;if(f==='enabled')p[f]=el.checked;else if(f==='price'||f==='quantity'||f==='unitCost')p[f]=Number(el.value)||0;else p[f]=el.value;if(f==='model')p.model=el.value;changed();render();}
function updateLiveValue(el){const e=state.expenses.find(x=>x.id===el.dataset.exp),p=state.products.find(x=>x.id===el.dataset.product);if(e){e[el.dataset.field]=Number(el.value)||0;if(e.kind==='payment'){$(`[data-exp="${e.id}"][data-field="amount"] + strong`)?.replaceChildren(document.createTextNode(`${nfmt(e.amount)}% + ${fmt(e.flatFee||0)}`))}const card=$(`[data-exp-card="${e.id}"]`);const number=card?.querySelector('input[type=number][data-field="amount"]');const range=card?.querySelector('input[type=range]');if(number&&el!==number)number.value=el.value;if(range&&el!==range)range.value=el.value;const strong=card?.querySelector('.amount-line strong');if(strong)strong.textContent=e.kind==='payment'?`${nfmt(e.amount)}% + ${fmt(e.flatFee||0)}`:e.kind==='percent'?`${nfmt(e.amount)}%`:fmt(e.amount);changed();renderKpis();renderFinance();renderScenario();renderCompetition();renderProductsTableOnly();return}if(p){p[el.dataset.field]=Number(el.value)||0;const sibling=document.querySelector(`[data-product="${p.id}"][data-field="${el.dataset.field}"]`);if(sibling&&sibling!==el)sibling.value=el.value;changed();renderKpis();renderFinance();renderScenario();renderCompetition();renderProductsTableOnly();}}
function renderProductsTableOnly(){const body=$('#productTable');if(!body)return;body.innerHTML=calc().productRows.map(r=>`<tr><td><b>${esc(r.product.name)}</b><div class="subtle">${modelLabel(r.product.model)}</div></td><td>${fmt(r.product.price)} / ${r.product.model==='year'?'year':r.product.model==='month'?'month':'event'}</td><td>${fmt(r.unitCost)} normalized / month</td><td class="${r.contribution<0?'negative':'positive'}">${fmt(r.contribution)} / sale / month</td><td>${nfmt(r.units)}</td><td>${fmt(r.monthlyRevenue)}</td><td>${fmt(r.assignedFixed)}</td><td class="${r.productProfit<0?'negative':'positive'}">${fmt(r.productProfit)}</td></tr>`).join('')||'<tr><td colspan="8">No active products.</td></tr>'}
function renderCurrentResults(){renderKpis();renderFinance();renderScenario();renderCompetition();renderProductsTableOnly();renderStatus()}
function scenarioPrompt(){let name=prompt('Name this custom scenario');if(!name?.trim())return;name=name.trim();if([...data.scenarios.map(s=>s.name),...state.customScenarios.map(s=>s.name)].includes(name))return toast('That scenario name already exists.');state.scenarioStates[name]=snapshotScenario();state.customScenarios.push({name});state.scenario=name;changed();render();toast('Custom scenario saved in this browser.')}
function backup(){download(new Blob([JSON.stringify({app:'SONAR Pricing & Cost Laboratory',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),'Pricing_Lab_Working_Model.json')}
async function importBackup(file){if(!file)return;try{const o=JSON.parse(await file.text()),incoming=o.state||o;if(!Array.isArray(incoming.expenses)||!Array.isArray(incoming.products))throw Error('This does not look like a Pricing Lab working-model backup.');if(!confirm('Import this model and replace the current browser working copy?'))return;state={...incoming,version:(state.version||0)+1,evaluation:null,confirmed:null};save();render();toast('Working model imported. Re-evaluate before confirming.')}catch(e){toast(e.message||'Could not import model.')}}
function restoreSuggestions(){if(!confirm('Restore suggested cost values and the original single-offer setup? Your custom lines and local model edits will be removed.'))return;state.expenses=clone(data.expenses);state.products=clone(data.products);state.scenario='Typical Operation';state.scenarioStates={};state.customScenarios=[];state.allocationMode='revenue';$('#allocationMode').value='revenue';state.evaluation=null;state.confirmed=null;state.version++;selectedProductId=state.products[0]?.id;save();render();toast('Suggested values restored.')}
function resetWork(){if(!confirm('Reset all saved pricing lab work in this browser to the original suggested model?'))return;localStorage.removeItem(STORAGE);state={expenses:clone(data.expenses),products:clone(data.products),scenario:'Typical Operation',scenarioStates:{},customScenarios:[],allocationMode:'revenue',version:0,evaluation:null,confirmed:null};selectedProductId=state.products[0].id;render();toast('Working model reset.')}
function bindDynamic(){document.addEventListener('input',e=>{const el=e.target;if((el.dataset.exp&&(el.dataset.field==='amount'||el.dataset.field==='flatFee'))||el.dataset.product&&(el.dataset.field==='price'||el.dataset.field==='quantity'||el.dataset.field==='unitCost'))updateLiveValue(el);if(el.id==='chartUnits'){renderFinance()}});document.addEventListener('change',e=>{const el=e.target;if(el.dataset.exp&&el.dataset.field!=='amount'&&el.dataset.field!=='flatFee')handleExpense(el);if(el.dataset.product&& !['price','quantity','unitCost'].includes(el.dataset.field))handleProduct(el);if(el.id==='chartUnits')renderFinance();if(el.id==='allocationMode'){state.allocationMode=el.value;changed();renderProductsTableOnly();renderScenario()}});document.addEventListener('click',e=>{const x=e.target.closest('[data-delete-exp]');if(x){state.expenses=state.expenses.filter(y=>y.id!==x.dataset.deleteExp);changed();render();toast('Custom expense removed.');return}const pdel=e.target.closest('[data-delete-product]');if(pdel){state.products=state.products.filter(y=>y.id!==pdel.dataset.deleteProduct);if(selectedProductId===pdel.dataset.deleteProduct)selectedProductId=state.products[0]?.id;changed();render();toast('Offer removed.');return}const choose=e.target.closest('[data-select-product]');if(choose){selectedProductId=choose.dataset.selectProduct;renderProducts();renderCompetition();renderFinance();return}const s=e.target.closest('[data-switch-scenario]');if(s)applyScenario(s.dataset.switchScenario)});$$('.cost-tab').forEach(b=>b.addEventListener('click',()=>{activeCostTab=b.dataset.kind;renderCostList()}));$('#addExpense').onclick=addExpense;$('#addProduct').onclick=addProduct;$('#restoreBtn').onclick=restoreSuggestions;$('#resetBtn').onclick=resetWork;$('#backupBtn').onclick=backup;$('#importFile').onchange=e=>{importBackup(e.target.files[0]);e.target.value=''};$('#saveScenario').onclick=scenarioPrompt;$('#scenarioSelect').onchange=e=>applyScenario(e.target.value);$('#evaluateBtn').onclick=evaluate;$('#reviseBtn').onclick=()=>$('#costs').scrollIntoView({behavior:'smooth'});$('#confirmBtn').onclick=confirmDecision;$('#justification').oninput=()=>{const ack=state.evaluation?.report?.hasWarnings&&!$('#ackWarnings').checked;$('#confirmBtn').disabled=!state.evaluation||state.evaluation.version!==state.version||$('#justification').value.trim().length<12||ack};$('#ackWarnings').onchange=()=>$('#confirmBtn').disabled=!state.evaluation||state.evaluation.version!==state.version||$('#justification').value.trim().length<12||state.evaluation.report.hasWarnings&&!$('#ackWarnings').checked;$('#downloadJson').onclick=()=>{const s=confirmedSnapshot();if(!s)return toast('Evaluation or confirmation is out of date.');download(new Blob([JSON.stringify(publicExport(s),null,2)],{type:'application/json'}),'Pricing_Decision_Data.json')};$('#downloadDocx').onclick=()=>{const s=confirmedSnapshot();if(!s)return toast('Evaluation or confirmation is out of date.');download(makeDocx(s),'Pricing_Decision_Report.docx')};$('#chartUnits').onchange=renderFinance;$('#allocationMode').onchange=e=>{state.allocationMode=e.target.value;changed();renderProductsTableOnly();renderScenario()};$$('nav a').forEach(a=>a.addEventListener('click',()=>{$$('nav a').forEach(x=>x.classList.toggle('active',x===a))}));const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){const a=$(`nav a[href="#${e.target.id}"]`);if(a){$$('nav a').forEach(x=>x.classList.toggle('active',x===a))}}}),{rootMargin:'-20% 0px -70% 0px'});$$('main section[id]').forEach(s=>obs.observe(s))}
function wire(){bindDynamic();}
starter().catch(e=>{document.querySelector('.content').innerHTML=`<article class="card" style="padding:24px;color:#ff999d">Could not load the bundled data: ${esc(e.message)}. Serve this folder over HTTP or use the published static site.</article>`;console.error(e)});
